try:
    from dataclasses import dataclass
    from typing import Any, List, Optional

    # -- Literal values --------------------------------------------
    @dataclass
    class Num:
        value: float

    @dataclass
    class Bool:
        value: bool

    @dataclass
    class Str:
        value: str

    @dataclass
    class Nil:
        pass

    # -- Variables -------------------------------------------------
    @dataclass
    class Name:
        name: str

    @dataclass
    class Assign:
        name: str
        value: Any  # expression

    # -- Arithmetic / logic ----------------------------------------
    @dataclass
    class BinOp:
        op:    str   # "+", "-", "*", "/", "%", "**",
                     # "==", "!=", "<", "<=", ">", ">=",
                     # "and", "or"
        left:  Any
        right: Any

    @dataclass
    class UnaryOp:
        op:    str   # "-", "not"
        operand: Any

    # -- Control flow ----------------------------------------------
    @dataclass
    class If:
        condition: Any
        then_body: List[Any]   # list of statements
        else_body: List[Any]

    @dataclass
    class While:
        condition: Any
        body: List[Any]

    @dataclass
    class Return:
        value: Any

    # -- Functions -------------------------------------------------
    @dataclass
    class FunDecl:
        name:   str
        params: List[str]
        body:   List[Any]

    @dataclass
    class Call:
        callee: Any
        args:   List[Any]

    # -- Statements ------------------------------------------------
    @dataclass
    class Print:
        value: Any

    @dataclass
    class Block:
        stmts: List[Any]

    print("AST node types defined.")
except Exception as e:
    print(f"Error: {e}")
